class Solution {
public:
    vector<vector<int>> res;
    vector<int> path;
    void go(int start, int n, int k) {
        if ((int)path.size() == k) {
            res.push_back(path);
            return;
        }
        for (int x = start; x <= n; x++) {
            path.push_back(x);
            go(x + 1, n, k);
            path.pop_back();
        }
    }
    vector<vector<int>> combine(int n, int k) {
        go(1, n, k);
        return res;
    }
};
